const pad = (value) => String(value).padStart(3, '0');

export const BUNDLED_CATALOG_PRODUCTS = definitions.map((item, index) => {
  const [slug, nameAr, nameEn, categoryCode, supplierCode, brand, model, productType,
    descriptionAr, descriptionEn, materialAr, materialEn, colorAr, colorEn,
    dimensions, price, origin] = item;
  const category = categories[categoryCode];
  const supplier = suppliers[supplierCode];
  const number = index + 1;
  const imageUrl = `/demo/products/catalog-100-${pad(number)}-${slug}.webp`;
  const id = `e1000000-0000-4000-8000-${String(number).padStart(12, '0')}`;
  const specificationId = (suffix) => `${id}-${suffix}`;

  return {
    id,
    product_id: id,
    slug: `catalog-${slug}`,
    product_name_ar: nameAr,
    product_name_en: nameEn,
    short_description_ar: descriptionAr,
    short_description_en: descriptionEn,
    full_description_ar: `${descriptionAr} صُمم هذا السجل التجريبي لإظهار البيانات الفنية المنظمة وربط المنتج بالمورد داخل منصة بُعد.`,
    full_description_en: `${descriptionEn} This demonstration record showcases structured technical data and supplier linkage inside BUOD.`,
    category_id: category[0],
    category_name_ar: category[1],
    category_name_en: category[2],
    supplier_id: supplier[0],
    supplier_slug: supplier[1],
    supplier_name_ar: supplier[2],
    supplier_name_en: supplier[3],
    buod_reference: `BUOD-${categoryCode}-DAT-${String(101 + index).padStart(6, '0')}`,
    product_type: productType,
    brand_name: brand,
    model_number: model,
    country_of_origin: origin,
    unit: 'piece',
    price,
    currency: 'SAR',
    in_stock: true,
    lead_time: `${3 + (index % 8)} weeks`,
    min_order_qty: 1,
    verification_status: 'verified',
    rights_confirmed: true,
    license_type: 'BUOD demonstration catalogue licence',
    license_download: false,
    license_commercial: false,
    license_modify: false,
    license_redistribute: false,
    version_number: '1.0',
    status: 'approved',
    visibility: 'public',
    is_featured: number <= 8,
    sort_order: 200 + number,
    created_at: `2026-08-23T${String(7 + Math.floor(index / 6)).padStart(2, '0')}:${String((index * 7) % 60).padStart(2, '0')}:00.000Z`,
    signed_image_url: imageUrl,
    image_error: false,
    available_formats: [],
    available_software: [],
    available_file_count: 0,
    file_metadata_error: false,
    download_count: 0,
    view_count: 0,
    product_images: [{ id: `${id}-image`, product_id: id, signed_url: imageUrl, is_primary: true, sort_order: 0 }],
    product_files: [],
    product_specifications: [
      { id: specificationId('material'), product_id: id, specification_name_ar: 'المادة الرئيسية', specification_name_en: 'Primary material', specification_code: 'MAT', value: `${materialEn} · ${materialAr}`, data_type: 'text', sort_order: 0 },
      { id: specificationId('finish'), product_id: id, specification_name_ar: 'اللون والتشطيب', specification_name_en: 'Colour and finish', specification_code: 'FIN', value: `${colorEn} · ${colorAr}`, data_type: 'text', sort_order: 1 },
      { id: specificationId('dimensions'), product_id: id, specification_name_ar: 'الأبعاد', specification_name_en: 'Dimensions', specification_code: 'DIM', value: dimensions, unit: 'mm', data_type: 'text', sort_order: 2 },
    ],
    product_materials: [{ id: `${id}-material`, product_id: id, material_name_ar: materialAr, material_name_en: materialEn, material_code: 'PRIMARY', material_type: 'primary', finish: colorEn, color: `${colorEn} · ${colorAr}`, quantity_per_product: 1, unit: 'set' }],
    detail_errors: { images: false, specifications: false, files: false, product_data: false, materials: false },
  };
});

export const getBundledCatalogProduct = (lookup) => BUNDLED_CATALOG_PRODUCTS.find((product) =>
  product.slug === lookup || product.id === lookup || product.buod_reference === lookup
);
